//wave gen from my previous wave gen shader
float wave(float xPos,float wavelength,float amplitude){//for 1 wave
        return (sin(xPos*wavelength))/amplitude;
    }

    float waveAdd(float alpha,float beta){//for more waves
        return 2.*cos((alpha-beta)/2.)*sin((alpha+beta)/2.);
    }

#define PI 3.1415926535897932384626433832795
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv.x *= iResolution.x/iResolution.y;
    uv.x -= .4;

    float lineWidth = .05;
    float loop = iTime*1.1;

    float anim = waveAdd(loop*2.,loop*.2);
    /*try other trig functions
    float anim = cos(loop);
    float anim = tan(loop);
    float anim = sin(loop);

    */
    vec3 col = vec3(step((1.-lineWidth+anim)/2.,length(uv-.5)));
    col -= vec3(step((1.+anim)/2.,length(uv/atan(loop/2.)-.5)));
    col += vec3(0.,step((.8-lineWidth+anim)/2.,length(uv*acos(loop/2.)-.5)),.0);
    col -= vec3(.0,step((.8+anim)/2.,length(uv-.5)),.0);
    col += vec3(.0,.0,step((.6-lineWidth+anim)/2.,length(uv*cos(loop)-.5)));
    col -= vec3(step((.6+anim)/2.,length(uv-.5)),.0,.0);
    col += vec3(.0,step((.4-lineWidth+anim)/2.,length(uv*cos(loop)-.5)),.0);
    col -= vec3(step((.4+anim)/2.,length(uv*tan(loop)-.5)),.0,.0);
    col += vec3(step((.2-lineWidth+anim)/2.,length(uv/sin(loop)-.5)),.0,.0);
    col -= vec3(.0,.0,step((.2+anim)/2.,length(uv*sin(loop)-.5)));

    // Output to screen
    fragColor = vec4(col,1.0);
}
